package com.gamehub.application.service; import com.gamehub.application.OperationsService; import java.time.Instant; import java.nio.file.Path; import java.util.*; public final class ReportService { private final OperationsService ops; public ReportService(OperationsService ops){this.ops=ops;} public Map<String,Long> counts()throws Exception{return ops.reportCounts();} public Map<String,Long> summary(long a,Instant f,Instant t)throws Exception{return ops.reportSummary(a,f,t);} public void export(long a,String c,Instant f,Instant t,Path p)throws Exception{ops.exportReportCsv(a,c,f,t,p);} }